module tb;
    logic [7:0] a = 8'h81, b = 8'h12, c = 8'h34, unknown = 8'hxz;
    logic [7:0] t0, t1, t2, t3;
    logic signed [15:0] w0, w1, w2, w3;
    bit [7:0] q0, q1, q2, q3;
    initial begin
        assign t0 = a;
        assign t1 = t0;
        assign t0 = b;
        assign t2 = t0;
        assign t3 = c;
        $display("CHECK: ordered=%h %h %h %h", t0, t1, t2, t3);
        deassign t1;
        t1 = 8'hff;
        assign t1 = c;
        assign t2 = a;
        assign t3 = b;
        assign t0 = c;
        $display("CHECK: replaced=%h %h %h %h", t0, t1, t2, t3);
        deassign t0;
        t0 = 8'h56;
        assign w0 = $signed(a);
        assign w1 = $signed(b);
        assign w2 = $signed(c);
        assign w3 = $signed(t0);
        assign q0 = unknown;
        assign q1 = a;
        assign q2 = b;
        assign q3 = c;
        $display("CHECK: casts=%h %h %h %h two=%h %h %h %h", w0, w1, w2, w3, q0, q1, q2, q3);
        #1;
        $display("CHECK: settled=%h %h %h %h", t0, t1, t2, t3);
        a = 8'h7e;
        b = 8'h22;
        c = 8'h43;
        #1;
        $display("CHECK: live=%h %h %h %h casts=%h %h %h %h", t0, t1, t2, t3, w0, w1, w2, w3);
        $finish(0);
    end
endmodule
